bin_num = input()
result = int(bin_num[0])
change = False
for i in range(1, len(bin_num)):
	if bin_num[i - 1] != bin_num[i]:
		if change:
			change = False
			result += 1
		else:
			change = True
	else:
		change = True
print(result + int(change and bin_num[len(bin_num) - 1] == '1'))
